class Solution {
    public int maximumGood(int[][] statements) {
        int n = statements.length;
        int ans = 0;
        int total = 1 << n;
        for (int mask = 0; mask < total; mask++) {
            boolean valid = true;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1) {
                    for (int j = 0; j < n; j++) {
                        if (statements[i][j] != 2) {
                            int expected = (mask >> j) & 1;
                            if (statements[i][j] != expected) {
                                valid = false;
                                break;
                            }
                        }
                    }
                    if (!valid) break;
                }
            }
            if (valid) {
