var maximumGood = function(statements) {
    const n = statements.length;
    let ans = 0;
    const total = 1 << n;
    for (let mask = 0; mask < total; mask++) {
        let valid = true;
        for (let i = 0; i < n; i++) {
            if ((mask >> i) & 1) {
                for (let j = 0; j < n; j++) {
                    if (statements[i][j] !== 2) {
                        const expected = (mask >> j) & 1;
                        if (statements[i][j] !== expected) {
                            valid = false;
                            break;
                        }
                    }
                }
                if (!valid) break;
            }
        }
        if (valid) {
            let bits = 0, temp = mask;
            while (temp > 0) {
                bits += temp & 1;
                temp >>= 1;
            }
            if (bits > ans) ans = bits;
        }
    }
    return ans;
};
